import React, { useEffect, useRef, useState } from 'react';
import './App.css';

const BASE_COUNT = 120;
const SAVE_MS = 400;
const SAVED_MESSAGE_MS = 1000;

export default function App() {
  const [liked, setLiked] = useState(false);
  const [status, setStatus] = useState('');
  const [failed, setFailed] = useState(false);
  const [requestCount, setRequestCount] = useState(0);

  // A save outlives the render that started it, so it reads the latest values from refs.
  const accepted = useRef(false);
  const latest = useRef(false);
  const saving = useRef(false);
  const serverDown = useRef<HTMLInputElement>(null);
  const saveTimer = useRef<number | undefined>(undefined);
  const messageTimer = useRef<number | undefined>(undefined);

  // The count follows the like, so the two can never disagree.
  const count = BASE_COUNT + (liked ? 1 : 0);

  useEffect(() => () => {
    window.clearTimeout(saveTimer.current);
    window.clearTimeout(messageTimer.current);
  }, []);

  function saveLike(value: boolean): Promise<boolean> {
    return new Promise((resolve, reject) => {
      saveTimer.current = window.setTimeout(() => {
        if (serverDown.current?.checked) reject(new Error('Server down'));
        else resolve(value);
      }, SAVE_MS);
    });
  }

  function startSave() {
    const value = latest.current;
    saving.current = true;
    setRequestCount((sent) => sent + 1);

    saveLike(value).then(
      () => {
        accepted.current = value;
        if (latest.current !== value) {
          startSave();
          return;
        }
        saving.current = false;
        setStatus('Saved');
        messageTimer.current = window.setTimeout(() => setStatus(''), SAVED_MESSAGE_MS);
      },
      () => {
        saving.current = false;
        latest.current = accepted.current;
        setLiked(accepted.current);
        setStatus('');
        setFailed(true);
      }
    );
  }

  function toggleLike() {
    latest.current = !latest.current;
    setLiked(latest.current);
    setFailed(false);
    setStatus('Saving…');
    window.clearTimeout(messageTimer.current);
    if (!saving.current) startSave();
  }

  return (
    <main className="page">
      <section className="card">
        <h1 className="title">Like Button</h1>
        <p className="subtitle">The screen answers first, and the server catches up.</p>

        <div className="row">
          <button
            className={'likeBtn' + (liked ? ' active' : '')}
            onClick={toggleLike}
            aria-pressed={liked}
            aria-label="like button"
          >
            <span className="icon" aria-hidden="true">👍</span>
            <span className="label">{liked ? 'Liked' : 'Like'}</span>
          </button>

          <div className="count" aria-label="like count">{count}</div>

          <p className="save-status" aria-live="polite">{status}</p>
        </div>

        {failed && <p className="save-error" role="alert">Could not save your like.</p>}

        <div className="server-tools">
          <label className="server-toggle">
            <input ref={serverDown} className="server-down" type="checkbox" />
            <span>Server down</span>
          </label>
          <p className="requests">
            Saves sent: <span className="request-count">{requestCount}</span>
          </p>
        </div>
      </section>
    </main>
  );
}

